with v(k,q) as (values ('dock.0','chock trailer wheels loading dock'),('dock.1','loading dock edge fall'),('dock.2','dock leveler keep clear'),('racking.0','pallet rack load capacity'),('racking.1','report damaged racking'),('conveyor.0','conveyor pinch point'),('conveyor.1','do not climb conveyor'),('conveyor.2','conveyor emergency stop pull cord'),('crane.0','overhead crane load stay clear'),('crane.1','do not stand under suspended load'),('welding.0','welding area arc eye protection'),('welding.1','hot work permit required'),('electrical.0','high voltage authorized personnel only electrical room'),('electrical.1','keep clear electrical panel 36 inches'),('electrical.2','arc flash hazard ppe required'),('arc_flash.0','arc flash and shock hazard'),('arc_flash.1','arc rated ppe required'),('high_voltage.0','danger high voltage keep out'),('high_voltage.1','substation authorized personnel'),('chemical.0','chemical storage area'),('chemical.1','corrosive chemicals wear ppe'),('chemical.2','safety data sheets location'),('compressed_gas.0','compressed gas cylinders secure chain')),
r as (select v.k, s.sku, row_number() over (partition by v.k order by s.score desc) rn from v cross join lateral finder.search_ids(v.q,null,null,null,null,10) s)
select r.k, r.rn, c.handle, left(c.title,90) t from r join lateral finder.cards(array[r.sku]) c on true where r.rn<=3 order by r.k, r.rn